'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// VARIABLES //

var stdev = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( stdev instanceof Error )
};


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof stdev, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', opts, function test( t ) {
	var y = stdev( NaN, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = stdev( 1.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a nonpositive `alpha`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = stdev( 0.0, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = stdev( -1.0, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = stdev( NINF, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `beta`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = stdev( 2.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = stdev( 2.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = stdev( 1.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = stdev( PINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = stdev( NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = stdev( NaN, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `beta <= 2`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = stdev( 2.0, 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = stdev( 2.0, 1.5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns the standard deviation of a log-logistic distribution', opts, function test( t ) {
	var expected;
	var alpha;
	var beta;
	var y;
	var i;

	expected = data.expected;
	alpha = data.alpha;
	beta = data.beta;
	for ( i = 0; i < alpha.length; i++ ) {
		y = stdev( alpha[ i ], beta[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 2 ), true, 'returns expected value' );
	}
	t.end();
});
